package config

import (
	"fmt"
	"strings"
)

// Markers around the generated environment-variable tables: the runtime
// table in docs/configuration.md and the contributor table in
// CONTRIBUTING.md.
const (
	EnvDocsStart = "<!-- env-vars:start (generated by cmd/gen_config_meta; do not edit) -->"
	EnvDocsEnd   = "<!-- env-vars:end -->"

	ContributorEnvDocsStart = "<!-- test-env-vars:start " +
		"(generated by cmd/gen_config_meta; do not edit) -->"
	ContributorEnvDocsEnd = "<!-- test-env-vars:end -->"
)

// EnvVarsMarkdown renders the runtime entries as the table
// docs/configuration.md carries.
func EnvVarsMarkdown() string {
	return envVarsMarkdown(EnvRuntime)
}

// ContributorEnvVarsMarkdown renders the contributor entries as the "Test
// environment" table CONTRIBUTING.md carries.
func ContributorEnvVarsMarkdown() string {
	return envVarsMarkdown(EnvContributor)
}

func envVarsMarkdown(kind EnvKind) string {
	var b strings.Builder
	b.WriteString("| Variable | Default | Description |\n|---|---|---|\n")
	for _, v := range envRegistry {
		if v.Kind != kind {
			continue
		}
		name := "`" + v.Name + "`"
		if v.File {
			name += " / `_FILE`"
		}
		fmt.Fprintf(&b, "| %s | %s | %s |\n", name, v.Default, v.Doc)
	}
	return b.String()
}

// envDocsBounds returns the offsets just after the start marker's line and
// at the end marker, or an error naming what is missing.
func envDocsBounds(doc, startMarker, endMarker string) (int, int, error) {
	start := strings.Index(doc, startMarker+"\n")
	end := strings.Index(doc, endMarker)
	switch {
	case start < 0:
		return 0, 0, fmt.Errorf("start marker %q not found on its own line", startMarker)
	case end < 0:
		return 0, 0, fmt.Errorf("end marker %q not found", endMarker)
	case end < start:
		return 0, 0, fmt.Errorf("end marker %q comes before the start marker", endMarker)
	}
	return start + len(startMarker) + 1, end, nil
}

// EnvDocsSection returns the text between the runtime markers of doc.
func EnvDocsSection(doc string) (string, error) {
	from, to, err := envDocsBounds(doc, EnvDocsStart, EnvDocsEnd)
	if err != nil {
		return "", err
	}
	return doc[from:to], nil
}

// ReplaceEnvDocsSection puts the runtime table between the markers of doc.
func ReplaceEnvDocsSection(doc string) (string, error) {
	from, to, err := envDocsBounds(doc, EnvDocsStart, EnvDocsEnd)
	if err != nil {
		return "", err
	}
	return doc[:from] + EnvVarsMarkdown() + doc[to:], nil
}

// ContributorEnvDocsSection returns the text between the contributor
// markers of doc.
func ContributorEnvDocsSection(doc string) (string, error) {
	from, to, err := envDocsBounds(doc, ContributorEnvDocsStart, ContributorEnvDocsEnd)
	if err != nil {
		return "", err
	}
	return doc[from:to], nil
}

// ReplaceContributorEnvDocsSection puts the contributor table between the
// contributor markers of doc.
func ReplaceContributorEnvDocsSection(doc string) (string, error) {
	from, to, err := envDocsBounds(doc, ContributorEnvDocsStart, ContributorEnvDocsEnd)
	if err != nil {
		return "", err
	}
	return doc[:from] + ContributorEnvVarsMarkdown() + doc[to:], nil
}
